WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_m_diff'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '异地出发相遇', 'kp-trv-m-diff', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "异地出发相遇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "并非同时出发。必须“截断时间轴”，强行把他们变成同时出发的状态。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲先走了 2 小时后，乙才从对面出发……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "相遇公式 S = (Va+Vb)×T 只有在两人【同时运动】时才成立。所以必须把“甲先走”的那部分路程单独剥离出来！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出总线段] --> B[算出甲先走的那段时间里, 独自走了多远 S独]\nB --> C[用总距离 S总 减去 S独, 得到剩下两人共同面对的距离 S余]\nC --> D[对 S余 使用标准相遇公式: S余 = (Va+Vb) * T共]\nD --> E[解出 T共]\nE --> F[总时间 = 独走时间 + T共]"}}]}$$ AS jsonb), NULL, '异地出发相遇的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "异地出发相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_m_diff", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
